#!/usr/bin/env bash
# Functional test of the headmesh_sbx ruleset without touching the host firewall.
#
# A throwaway "router" container (its own netns, NET_ADMIN) plays the host: it
# applies the real rules generated by headmesh-sandbox-firewall to the
# interface facing a fake sandbox network, forwards and masquerades. Probes run
# from fake sandbox containers (regular and YOLO addresses) towards the router
# itself, a fake LAN host, a CGNAT address and the internet. The router
# blackholes 100.64.0.0/10 and 192.168.0.0/16, so even a broken ruleset can't
# leak a probe into the real tailnet or LAN.
#
# Usage: selftest.sh [IMAGE]   (IMAGE needs nft, ip, nc; the sandbox image works)
set -euo pipefail

IMAGE=${1:-${HM_FIREWALL_TEST_IMAGE:-ghcr.io/headmesh-dev/sandbox:dev}}
HERE=$(cd "$(dirname "$0")" && pwd)
P=hm-fwtest-$$
NET_SBX=$P-sbx     # 172.31.252.0/24, plays the sandbox bridge
NET_LAN=$P-lan     # 10.99.0.0/24, carries the fake LAN (10.98.0.0/24 behind it)
ROUTER=$P-router
LANHOST=$P-lan
fail=0

cleanup() {
    docker rm -f "$ROUTER" "$LANHOST" "$P-s-regular" "$P-s-yolo" >/dev/null 2>&1 || true
    docker network rm "$NET_SBX" "$NET_LAN" >/dev/null 2>&1 || true
}
[ "${KEEP:-0}" = 1 ] || trap cleanup EXIT

run_d() { docker run -d --rm --entrypoint "" --cap-drop ALL "$@" >/dev/null; }

docker network create --subnet 172.31.252.0/24 "$NET_SBX" >/dev/null
docker network create --subnet 10.99.0.0/24 "$NET_LAN" >/dev/null

# Fake LAN host: TCP 80 and UDP 41641 (allowed WireGuard range) and UDP 5353.
# Probes target 10.98.0.20, an address Docker doesn't know about, routed by the
# router via 10.99.0.20. (Docker's raw PREROUTING anti-spoofing drops bridged
# packets to a container's own IP that arrive from another bridge, which would
# mask what this test is about.)
LAN_IP=10.98.0.20
run_d --name "$LANHOST" --network "$NET_LAN" --ip 10.99.0.20 --cap-add NET_ADMIN "$IMAGE" sh -c \
    "ip addr add $LAN_IP/32 dev eth0 && (nc -lk 80 >/dev/null &) && (nc -luk 41641 > /tmp/udp41641 &) && (nc -luk 5353 > /tmp/udp5353 &) && sleep infinity"

# Router: own netns, forwarding on, masquerade out of every non-sandbox port.
run_d --name "$ROUTER" --network bridge --cap-add NET_ADMIN --cap-add NET_RAW \
    --sysctl net.ipv4.ip_forward=1 "$IMAGE" sleep infinity
docker network connect --ip 172.31.252.2 "$NET_SBX" "$ROUTER"
docker network connect --ip 10.99.0.2 "$NET_LAN" "$ROUTER"
SBX_IF=$(docker exec "$ROUTER" sh -c "ip -o -4 addr show | awk '/172\\.31\\.252\\.2\\//{print \$2}'")
GW=$(docker network inspect bridge -f '{{(index .IPAM.Config 0).Gateway}}')
docker exec "$ROUTER" sh -c "
    ip route replace default via $GW
    ip route add $LAN_IP/32 via 10.99.0.20
    ip route add blackhole 100.64.0.0/10
    ip route add blackhole 192.168.0.0/16
    nft add table ip nat
    nft add chain ip nat post '{ type nat hook postrouting priority srcnat; }'
    nft add rule ip nat post oifname != \"$SBX_IF\" masquerade
    (nc -lk 8080 >/dev/null &)
"

apply_rules() { # $1 = YOLO_ALLOW_LAN
    local conf
    conf=$(mktemp)
    cat >"$conf" <<EOF
SBX_BRIDGE=$SBX_IF
SBX_SUBNET=172.31.252.0/24
SBX_REGULAR_IP=172.31.252.10
SBX_YOLO_IP=172.31.252.11
YOLO_ALLOW_LAN=$1
LAN_SUBNETS="10.98.0.0/24"
EOF
    HEADMESH_SANDBOX_FIREWALL_CONF=$conf "$HERE/headmesh-sandbox-firewall" render |
        docker exec -i "$ROUTER" nft -f -
    rm -f "$conf"
}

start_sandbox() { # name ip
    run_d --name "$1" --network "$NET_SBX" --ip "$2" --cap-add NET_ADMIN "$IMAGE" \
        sh -c "ip route replace default via 172.31.252.2 && (nc -lk 8780 >/dev/null &) && sleep infinity"
}

expect() { # container want(allow|deny) label cmd...
    local c=$1 want=$2 label=$3
    shift 3
    if docker exec "$c" timeout 6 sh -c "$*" >/dev/null 2>&1; then got=allow; else got=deny; fi
    if [ "$got" = "$want" ]; then
        printf 'PASS  %-8s %-5s %s\n' "${c##*-}" "$want" "$label"
    else
        printf 'FAIL  %-8s want %-5s got %-5s %s\n' "${c##*-}" "$want" "$got" "$label"
        fail=1
    fi
}

udp_seen() { # port marker → was the datagram received by the LAN host?
    docker exec "$LANHOST" grep -q "$2" "/tmp/udp$1"
}

start_sandbox "$P-s-regular" 172.31.252.10
start_sandbox "$P-s-yolo" 172.31.252.11

echo "== YOLO_ALLOW_LAN=0 (Regular policy for both addresses)"
apply_rules 0
for c in "$P-s-regular" "$P-s-yolo"; do
    expect "$c" allow "internet tcp 1.1.1.1:443" nc -z -w4 1.1.1.1 443
    expect "$c" deny "host itself 172.31.252.2:8080 (a host service open to Docker bridges)" nc -z -w3 172.31.252.2 8080
    expect "$c" deny "host's other interface 10.99.0.2:8080" nc -z -w3 10.99.0.2 8080
    expect "$c" deny "LAN tcp $LAN_IP:80" nc -z -w3 $LAN_IP 80
    expect "$c" deny "CGNAT/tailnet 100.64.0.1:443" nc -z -w3 100.64.0.1 443
    expect "$c" deny "LAN router 192.168.1.254:80" nc -z -w3 192.168.1.254 80
    expect "$c" deny "link-local 169.254.169.254:80" nc -z -w3 169.254.169.254 80
done
for c in "$P-s-regular" "$P-s-yolo"; do
    m="hm-$c-$RANDOM"
    docker exec "$c" sh -c "echo $m | nc -u -w1 $LAN_IP 41641; echo $m | nc -u -w1 $LAN_IP 5353" || true
    sleep 1
    if udp_seen 41641 "$m"; then echo "PASS  ${c##*-} allow LAN udp 41641 (tailscale direct path)"; else echo "FAIL  ${c##*-} LAN udp 41641 not received"; fail=1; fi
    if udp_seen 5353 "$m"; then echo "FAIL  ${c##*-} LAN udp 5353 was received"; fail=1; else echo "PASS  ${c##*-} deny  LAN udp 5353"; fi
done
# Host-initiated connection into the sandbox still works (replies are allowed).
if docker exec "$ROUTER" timeout 5 nc -z -w3 172.31.252.10 8780 2>/dev/null; then
    echo "PASS  router   allow host -> sandbox 8780 (reply path)"
else
    echo "FAIL  router   host -> sandbox 8780"; fail=1
fi

echo "== YOLO_ALLOW_LAN=1"
apply_rules 1
expect "$P-s-yolo" allow "YOLO LAN tcp $LAN_IP:80" nc -z -w3 $LAN_IP 80
expect "$P-s-regular" deny "Regular LAN tcp $LAN_IP:80" nc -z -w3 $LAN_IP 80
expect "$P-s-yolo" deny "YOLO host itself 172.31.252.2:8080" nc -z -w3 172.31.252.2 8080
expect "$P-s-yolo" deny "YOLO CGNAT/tailnet 100.64.0.1:443" nc -z -w3 100.64.0.1 443

echo "== drop counters on the router"
docker exec "$ROUTER" nft list table inet headmesh_sbx | grep -E 'comment "(sandbox -> host|private/reserved v4|YOLO_ALLOW_LAN|tailscale direct paths)"' | sed 's/^\s*/  /'

if [ $fail = 0 ]; then echo "selftest: all probes behaved as expected"; else echo "selftest: FAILURES"; fi
exit $fail
